def transform(grid):
    h, w = len(grid), len(grid[0])
    # The dominant color fills the repeating tiles. The other frequent color
    # forms the lattice, with occasional colored values written at crossings.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Lattice rows and columns have a strong majority of the non-background
    # line color. Retain those carrying any encoded colored crossing.
    line_color = max((v for v in counts if v != background),
                     key=lambda v: counts[v])
    rows = [r for r in range(h)
            if sum(x == line_color for x in grid[r]) > w // 2]
    cols = [c for c in range(w)
            if sum(grid[r][c] == line_color for r in range(h)) > h // 2]

    # Select the repeated crossings and convert the tile background to 9.
    out = [[9 if grid[r][c] == background else grid[r][c] for c in cols]
           for r in rows]
    # Remove the unmarked outermost lattice margins.
    while len(out) > 1 and all(v == 9 for v in out[0]):
        out.pop(0)
    while len(out) > 1 and all(v == 9 for v in out[-1]):
        out.pop()
    while out and len(out[0]) > 1 and all(row[0] == 9 for row in out):
        for row in out:
            row.pop(0)
    while out and len(out[0]) > 1 and all(row[-1] == 9 for row in out):
        for row in out:
            row.pop()
    return out
